import { FastifyInstance } from "fastify";
import type { PrismaClient } from '../../../generated/prisma/client';
import bcrypt from "bcrypt";
import MqttService, { createWebcamOnMQTT } from "../../app/mqtt";

const saltRounds = 10;
const mqttClient = MqttService.getClient();

// Credentials are generated by agrosmart_camera/setup_mqtt_client.py
const WEBCAM_ID_REGEX = /^cam_[a-z0-9]{8}$/;

export function addWebcam(fastify: FastifyInstance, prisma: PrismaClient) {
    fastify.post(
        '/webcam',
        {
            schema: {
                tags: ['Webcam'],
                summary: 'Add a webcam to the user',
                description: 'Add a webcam associated to the authenticated user',
                headers: {
                    type: 'object',
                    properties: {
                        authorization: { type: 'string' }
                    },
                    required: ['authorization']
                },
                body: {
                    type: 'object',
                    properties: {
                        id: {
                            type: 'string',
                            description: 'ID of the webcam, also used as its MQTT username'
                        },
                        name: {
                            type: 'string',
                            description: 'Name of the webcam'
                        },
                        password: {
                            type: 'string',
                            description: 'Password generated by the webcam'
                        },
                    },
                    required: ['id', 'name', 'password'],
                },
                response: {
                    200: {
                        description: 'Webcam successfully added',
                        type: 'object',
                        properties: {
                            success: { type: 'boolean' },
                            message: { type: 'string' },
                        },
                    },
                    400: {
                        description: 'Invalid webcam ID or password',
                        type: 'object',
                        properties: {
                            success: { type: 'boolean' },
                            message: { type: 'string' },
                        }
                    },
                    401: {
                        description: 'Unauthorized request',
                        type: 'object',
                        properties: {
                            success: { type: 'boolean' },
                            message: { type: 'string' },
                        }
                    },
                    409: {
                        description: 'Webcam already exists',
                        type: 'object',
                        properties: {
                            success: { type: 'boolean' },
                            message: { type: 'string' },
                        },
                    },
                    500: {
                        description: 'Internal server error',
                        type: 'object',
                        properties: {
                            success: { type: 'boolean' },
                            message: { type: 'string' },
                        },
                    },
                },
            },
        },
        async function handler(request, reply) {
            const username = request.user;

            const logger = request.server.log;
            const { id, name, password } = request.body as {
                id: string;
                name: string;
                password: string;
            };

            if (!WEBCAM_ID_REGEX.test(id)) {
                logger.info({ username, id }, 'Invalid webcam ID');
                return reply.status(400).send({
                    success: false,
                    message: 'Invalid webcam ID or password'
                });
            }

            try {
                logger.info({ username, id, name }, 'Adding webcam');
                await prisma.webcam.create({
                    data: {
                        id,
                        name,
                        username,
                        pswHash: await bcrypt.hash(password, saltRounds),
                    },
                });
                await createWebcamOnMQTT(id, password, username, mqttClient);
                logger.info({ username, id, name }, 'Webcam successfully added');
            } catch (error) {
                // @ts-ignore
                if (error.code === 'P2002') {
                    logger.info({ username, id, name }, 'Webcam already exists');
                    return reply.status(409).send({
                        success: false,
                        message: 'Webcam already exists'
                    });
                }
                logger.error({ error, username, id, name }, 'Error during webcam creation');
                return reply.status(500).send({
                    success: false,
                    message: 'Error during webcam creation. Check log for further information',
                });
            }

            return reply.send({ success: true, message: 'Webcam added successfully!' });
        },
    );
}